<div id="toast" class="toast"></div>



<script>

/* ===================== DOM HELPER (no innerHTML) ===================== */

function create(tag, options) {

  options = options || {};

  const node = document.createElement(tag);

  if (options.className) node.className = options.className;

  if (options.text !== undefined) node.textContent = options.text;

  if (options.attrs) {

    Object.keys(options.attrs).forEach(function (key) {

      node.setAttribute(key, options.attrs[key]);

    });

  }

  if (options.style) {

    Object.keys(options.style).forEach(function (key) {

      node.style[key] = options.style[key];

    });

  }

  if (options.events) {

    Object.keys(options.events).forEach(function (key) {

      node.addEventListener(key, options.events[key]);

    });

  }

  if (options.children) {

    options.children.forEach(function (child) { node.appendChild(child); });

  }

  if (options.parent) {

    options.parent.appendChild(node);

  }

  return node;

}



function clear(node) {

  while (node.firstChild) {

    node.removeChild(node.firstChild);

  }

}



/* ===================== STATE ===================== */

function defaultState() {

  return {

    title: "Late Night Confession",

    platform: "iMessage",

    time: "9:41",

    carrier: "5G",

    roles: [

      { id: "r1", name: "Alex", color: "#4f46e5", emoji: "🧑", isMe: false },

      { id: "r2", name: "Jordan", color: "#0ea5e9", emoji: "👤", isMe: true }

    ],

    beats: [

      { id: "b1", roleId: "r1", type: "text", text: "are you awake?", shotNotes: "Close-up on lock screen, dim bedroom glow. 2-second hold.", flags: ["lock screen"] },

      { id: "b2", roleId: "r2", type: "text", text: "yeah. can't sleep.", shotNotes: "Over-shoulder, thumb hovering keyboard. Soft blue light on face.", flags: ["typing indicator"] },

      { id: "b3", roleId: "r1", type: "text", text: "i need to tell you something", shotNotes: "Tight on message bubble, slight camera push-in.", flags: ["suspense"] }

    ],

    selectedBeatId: null

  };

}



function loadFromStorage() {

  const raw = localStorage.getItem('chatStoryboardStudio');

  if (!raw) return null;

  try { return JSON.parse(raw); } catch (e) { return null; }

}



let state = loadFromStorage() || defaultState();



/* ===================== DOM REFS ===================== */

const refs = {

  roleList: document.getElementById('roleList'),

  chatStage: document.getElementById('chatStage'),

  inspector: document.getElementById('inspector'),

  projectTitle: document.getElementById('projectTitle'),

  projectPlatform: document.getElementById('projectPlatform'),

  projectTime: document.getElementById('projectTime'),

  projectCarrier: document.getElementById('projectCarrier'),

  statusTime: document.getElementById('statusTime'),

  statusCarrier: document.getElementById('statusCarrier'),

  chatTitle: document.getElementById('chatTitle'),

  chatSubtitle: document.getElementById('chatSubtitle'),

  checksBackdrop: document.getElementById('checksBackdrop'),

  checksDrawer: document.getElementById('checksDrawer'),

  checksSummary: document.getElementById('checksSummary'),

  checksList: document.getElementById('checksList'),

  briefBackdrop: document.getElementById('briefBackdrop'),

  briefDrawer: document.getElementById('briefDrawer'),

  briefOutput: document.getElementById('briefOutput'),

  fileInput: document.getElementById('fileInput'),

  newRoleName: document.getElementById('newRoleName'),

  newRoleColor: document.getElementById('newRoleColor'),

  newRoleEmoji: document.getElementById('newRoleEmoji'),

  newRoleIsMe: document.getElementById('newRoleIsMe'),

  toast: document.getElementById('toast')

};



/* ===================== INIT ===================== */

function init() {

  refs.projectTitle.value = state.title;

  refs.projectPlatform.value = state.platform;

  refs.projectTime.value = state.time;

  refs.projectCarrier.value = state.carrier;

  updateStatusBar();

  renderRoles();

  renderChat();

  renderInspector();

  wireEvents();

}



function persist() {

  localStorage.setItem('chatStoryboardStudio', JSON.stringify(state));

}



function updateStatusBar() {

  refs.statusTime.textContent = state.time || '--:--';

  refs.statusCarrier.textContent = state.carrier || '';

  refs.chatTitle.textContent = state.title || 'Chat';

  const others = state.roles.filter(function (r) { return !r.isMe; }).map(function (r) { return r.name; }).join(', ');

  refs.chatSubtitle.textContent = others ? 'with ' + others : 'new message';

}



function updateProject() {

  state.title = refs.projectTitle.value;

  state.platform = refs.projectPlatform.value;

  state.time = refs.projectTime.value;

  state.carrier = refs.projectCarrier.value;

  updateStatusBar();

  persist();

}



/* ===================== ROLES ===================== */

function renderRoles() {

  clear(refs.roleList);

  state.roles.forEach(function (role) {

    const card = create('div', {

      className: 'role-card' + (role.isMe ? ' active' : ''),

      attrs: { 'data-role-id': role.id },

      parent: refs.roleList

    });



    const avatar = create('div', {

      className: 'role-avatar',

      text: role.emoji || '•',

      style: { backgroundColor: role.color },

      parent: card

    });



    const info = create('div', { parent: card });



    const nameLine = create('div', {

      className: 'role-name',

      parent: info

    });

    create('span', { text: role.name, parent: nameLine });

    if (role.isMe) {

      create('span', { text: ' (me)', style: { fontSize: '11px', color: 'var(--primary)' }, parent: nameLine });

    }



    create('div', {

      className: 'role-meta',

      text: state.beats.filter(function (b) { return b.roleId === role.id; }).length + ' beats',

      parent: info

    });



    create('button', {

      className: 'ghost',

      text: '×',

      attrs: { title: 'Delete' },

      events: { click: function () { deleteRole(role.id); } },

      parent: card

    });

  });

}



function addRole() {

  const name = refs.newRoleName.value.trim();

  const color = refs.newRoleColor.value;

  const emoji = refs.newRoleEmoji.value.trim() || '👤';

  const isMe = refs.newRoleIsMe.checked;

  if (!name) return toast('Enter a role name');



  if (isMe) {

    state.roles.forEach(function (r) { r.isMe = false; });

  }

  state.roles.push({ id: 'r' + Date.now(), name: name, color: color, emoji: emoji, isMe: isMe });



  refs.newRoleName.value = '';

  refs.newRoleEmoji.value = '🧑';

  refs.newRoleIsMe.checked = false;



  renderRoles();

  renderChat();

  persist();

}



function deleteRole(id) {

  if (state.roles.length <= 1) return toast('Keep at least one role');

  state.roles = state.roles.filter(function (r) { return r.id !== id; });

  state.beats.forEach(function (b) {

    if (b.roleId === id) b.roleId = state.roles[0].id;

  });

  renderRoles();

  renderChat();

  renderInspector();

  persist();

}



function getRole(id) {

  return state.roles.find(function (r) { return r.id === id; }) || state.roles[0];

}



/* ===================== BEATS / CHAT ===================== */

function addBeat(type) {

  const meRole = state.roles.find(function (r) { return r.isMe; }) || state.roles[0];

  const lastRole = state.beats.length ? getRole(state.beats[state.beats.length - 1].roleId) : meRole;

  const role = type === 'status' ? null : lastRole;



  let text = '';

  if (type === 'image') text = '[image placeholder]';

  else if (type === 'voice') text = '0:08 voice memo';



  const beat = {

    id: 'b' + Date.now(),

    roleId: role ? role.id : null,

    type: type,

    text: text,

    shotNotes: '',

    flags: []

  };



  state.beats.push(beat);

  state.selectedBeatId = beat.id;

  renderChat();

  renderInspector();

  persist();

}



function moveBeat(id, dir) {

  const idx = state.beats.findIndex(function (b) { return b.id === id; });

  const newIdx = idx + dir;

  if (newIdx < 0 || newIdx >= state.beats.length) return;

  const tmp = state.beats[idx];

  state.beats[idx] = state.beats[newIdx];

  state.beats[newIdx] = tmp;

  renderChat();

  persist();

}



function deleteBeat(id) {

  state.beats = state.beats.filter(function (b) { return b.id !== id; });

  if (state.selectedBeatId === id) state.selectedBeatId = null;

  renderChat();

  renderInspector();

  persist();

}



function selectBeat(id) {

  state.selectedBeatId = id;

  renderChat();

  renderInspector();

}



function renderChat() {

  clear(refs.chatStage);

  state.beats.forEach(function (beat, i) {

    const isStatus = beat.type === 'status';

    const role = isStatus ? null : getRole(beat.roleId);

    const isMe = role && role.isMe;

    const className = 'bubble ' + beat.type + ' ' + (isStatus ? 'status' : (isMe ? 'me' : 'them')) + (state.selectedBeatId === beat.id ? ' selected' : '');



    const bubble = create('div', {

      className: className,

      attrs: { 'data-beat-id': beat.id },

      events: { click: function () { selectBeat(beat.id); } },

      parent: refs.chatStage

    });



    if (beat.type === 'image') {

      const img = create('img', { attrs: { alt: beat.text } });

      bubble.appendChild(img);

      create('div', { className: 'time', text: beat.text, parent: bubble });

    } else if (beat.type === 'voice') {

      create('div', { className: 'voice', text: '🎙 ' + beat.text, parent: bubble });

      create('div', { className: 'time', text: 'voice note', parent: bubble });

    } else {

      create('div', { text: beat.text, parent: bubble });

      create('div', { className: 'time', text: (role ? role.name : '') + ' • beat ' + (i + 1), parent: bubble });

    }



    create('div', { className: 'beat-num', text: String(i + 1), parent: bubble });

  });

}



/* ===================== INSPECTOR ===================== */

function renderInspector() {

  clear(refs.inspector);

  const beat = state.beats.find(function (b) { return b.id === state.selectedBeatId; });

  if (!beat) {

    create('div', { className: 'empty-state', text: 'Select a message bubble to edit its content, sender, and shot-quality notes.', parent: refs.inspector });

    return;

  }



  const index = state.beats.indexOf(beat) + 1;



  // Type field

  createFieldLabel('Beat #' + index + ' Type', refs.inspector);

  const typeSelect = create('select', { parent: refs.inspector });

  [

    ['text', 'Text'],

    ['image', 'Image'],

    ['voice', 'Voice memo'],

    ['status', 'Status / system']

  ].forEach(function (opt) {

    create('option', { text: opt[1], attrs: { value: opt[0], selected: beat.type === opt[0] ? 'selected' : null }, parent: typeSelect });

  });

  typeSelect.addEventListener('change', function () { updateBeat(beat.id, 'type', typeSelect.value); });



  // Sender field

  createFieldLabel('Sender', refs.inspector);

  const roleSelect = create('select', { parent: refs.inspector });

  if (beat.type === 'status') {

    create('option', { text: '— System —', attrs: { value: '', selected: beat.roleId === null ? 'selected' : null }, parent: roleSelect });

  }

  state.roles.forEach(function (r) {

    const label = r.name + (r.isMe ? ' (me)' : '');

    create('option', { text: label, attrs: { value: r.id, selected: beat.roleId === r.id ? 'selected' : null }, parent: roleSelect });

  });

  roleSelect.addEventListener('change', function () { updateBeat(beat.id, 'roleId', roleSelect.value || null); });



  // Text field

  createFieldLabel('Message / Label', refs.inspector);

  const textArea = create('textarea', { parent: refs.inspector });

  textArea.value = beat.text;

  textArea.addEventListener('input', function () { updateBeat(beat.id, 'text', textArea.value); });



  // Shot notes field

  createFieldLabel('Shot-quality notes', refs.inspector);

  const notesArea = create('textarea', {

    attrs: { placeholder: 'Camera angle, lighting, lens, motion, duration, prop details…' },

    parent: refs.inspector

  });

  notesArea.value = beat.shotNotes;

  notesArea.addEventListener('input', function () { updateBeat(beat.id, 'shotNotes', notesArea.value); });

  create('div', { className: 'hint', text: 'Describe how this screenshot should be captured or designed.', parent: refs.inspector });



  // Flags

  createFieldLabel('Flags', refs.inspector);

  const tags = create('div', { className: 'tags', parent: refs.inspector });

  const flagOptions = ['lock screen', 'typing indicator', 'suspense', 'reveal', 'cutaway', 'CGUI', 'reaction', 'time jump'];

  flagOptions.forEach(function (tag) {

    const active = (beat.flags || []).indexOf(tag) !== -1;

    create('span', {

      className: 'tag' + (active ? ' active' : ''),

      text: tag,

      events: { click: function () { toggleFlag(beat.id, tag); } },

      parent: tags

    });

  });



  // Action buttons

  const btnRow = create('div', { style: { display: 'flex', gap: '8px', marginTop: '8px' }, parent: refs.inspector });

  create('button', {

    text: '↑ Move up',

    attrs: { disabled: state.beats[0].id === beat.id ? 'disabled' : null },

    events: { click: function () { moveBeat(beat.id, -1); } },

    parent: btnRow

  });

  create('button', {

    text: '↓ Move down',

    attrs: { disabled: state.beats[state.beats.length - 1].id === beat.id ? 'disabled' : null },

    events: { click: function () { moveBeat(beat.id, 1); } },

    parent: btnRow

  });

  create('button', {

    className: 'danger',

    text: 'Delete beat',

    style: { marginLeft: 'auto' },

    events: { click: function () { deleteBeat(beat.id); } },

    parent: btnRow

  });

}



function createFieldLabel(text, parent) {

  return create('label', { className: 'field', text: text, parent: parent });

}



function updateBeat(id, key, value) {

  const beat = state.beats.find(function (b) { return b.id === id; });

  if (!beat) return;

  beat[key] = value;

  renderChat();

  renderInspector();

  persist();

}



function toggleFlag(id, tag) {

  const beat = state.beats.find(function (b) { return b.id === id; });

  if (!beat.flags) beat.flags = [];

  const pos = beat.flags.indexOf(tag);

  if (pos !== -1) beat.flags.splice(pos, 1);

  else beat.flags.push(tag);

  renderInspector();

  persist();

}



/* ===================== COHERENCE CHECKS ===================== */

function runChecks() {

  const issues = [];



  if (!state.title.trim()) {

    issues.push({ level: 'warn', title: 'Missing project title', desc: 'Add a title so the brief is identifiable.' });

  }



  if (state.beats.length === 0) {

    issues.push({ level: 'err', title: 'No beats', desc: 'Add at least one message beat.' });

  }



  if (state.roles.length < 2 && state.beats.some(function (b) { return b.type !== 'status'; })) {

    issues.push({ level: 'warn', title: 'Only one role', desc: 'Real chats usually involve at least two participants.' });

  }



  const noNotes = state.beats.filter(function (b) { return !b.shotNotes || !b.shotNotes.trim(); });

  if (noNotes.length) {

    issues.push({ level: 'warn', title: noNotes.length + ' beat(s) lack shot notes', desc: 'Production-quality storyboards should include camera/lens/lighting notes for every beat.' });

  }



  state.beats.forEach(function (b, i) {

    if (b.type === 'image' && (!b.text || b.text === '[image placeholder]')) {

      issues.push({ level: 'err', title: 'Beat ' + (i + 1) + ': image lacks description', desc: 'Describe what the image shows.' });

    }

    if (b.type === 'text' && b.text.length > 300) {

      issues.push({ level: 'warn', title: 'Beat ' + (i + 1) + ': very long message', desc: 'Consider splitting into smaller bubbles for readability.' });

    }

  });



  for (let i = 0; i < state.beats.length - 1; i++) {

    const cur = state.beats[i];

    const next = state.beats[i + 1];

    if (cur.type !== 'status' && next.type !== 'status' && cur.roleId === next.roleId) {

      issues.push({ level: 'warn', title: 'Beat ' + (i + 1) + ' & ' + (i + 2) + ': same sender twice', desc: 'Back-to-back messages from one sender can look unnatural unless intentional.' });

    }

  }



  const sad = ['sorry', 'dead', 'never', 'hate', 'cry', 'miss'];

  const happy = ['love', 'great', 'yes', 'happy', 'awesome', 'thanks'];

  for (let i = 1; i < state.beats.length; i++) {

    const prevText = (state.beats[i - 1].text || '').toLowerCase();

    const curText = (state.beats[i].text || '').toLowerCase();

    const prevSad = sad.some(function (w) { return prevText.indexOf(w) !== -1; });

    const curHappy = happy.some(function (w) { return curText.indexOf(w) !== -1; });

    if (prevSad && curHappy) {

      issues.push({ level: 'warn', title: 'Beat ' + i + ' to ' + (i + 1) + ': possible abrupt tone shift', desc: 'A sudden swing from negative to positive may need a bridging beat.' });

    }

  }



  if (!issues.length) {

    issues.push({ level: 'ok', title: 'All coherence checks passed', desc: 'Your storyboard looks consistent and production-ready.' });

  }



  renderChecks(issues);

  openChecks();

}



function renderChecks(issues) {

  clear(refs.checksList);

  issues.forEach(function (iss) {

    const bg = iss.level === 'err' ? '#fef2f2' : iss.level === 'warn' ? '#fffbeb' : '#f0fdf4';

    const border = iss.level === 'err' ? '#fecaca' : iss.level === 'warn' ? '#fde68a' : '#bbf7d0';

    const icon = iss.level === 'err' ? '❌' : iss.level === 'warn' ? '⚠️' : '✅';



    const item = create('div', {

      className: 'check-item',

      style: { backgroundColor: bg, borderColor: border },

      parent: refs.checksList

    });



    create('div', { className: 'check-icon', text: icon, parent: item });

    const body = create('div', { parent: item });

    create('div', { className: 'check-title', text: iss.title, parent: body });

    create('div', { className: 'check-desc', text: iss.desc, parent: body });

  });



  const errCount = issues.filter(function (i) { return i.level === 'err'; }).length;

  const warnCount = issues.filter(function (i) { return i.level === 'warn'; }).length;

  refs.checksSummary.className = 'coherence-badge ' + (errCount ? 'err' : warnCount ? 'warn' : 'ok');

  refs.checksSummary.textContent = errCount ? errCount + ' error(s)' : warnCount ? warnCount + ' warning(s)' : 'All clear';

}



function openChecks() { refs.checksBackdrop.classList.add('open'); refs.checksDrawer.classList.add('open'); }

function closeChecks() { refs.checksBackdrop.classList.remove('open'); refs.checksDrawer.classList.remove('open'); }



/* ===================== IMAGE BRIEF ===================== */

function generateBrief() {

  const lines = [];

  lines.push('PHONE-CHAT SCREENSHOT STORYBOARD BRIEF');

  lines.push('Generated: ' + new Date().toLocaleString());

  lines.push('Project: ' + (state.title || 'Untitled'));

  lines.push('Platform: ' + state.platform);

  lines.push('Simulated time: ' + state.time + ' | Carrier: ' + state.carrier);

  lines.push('');



  lines.push('CAST / ROLES');

  state.roles.forEach(function (r) {

    lines.push('• ' + r.name + (r.isMe ? ' (protagonist / "me")' : ' (contact)'));

    lines.push('  Avatar: ' + r.emoji + ' | Bubble color: ' + r.color);

  });

  lines.push('');



  lines.push('SHOT LIST (' + state.beats.length + ' beats)');

  state.beats.forEach(function (b, i) {

    const roleName = b.type === 'status' ? 'SYSTEM' : getRole(b.roleId).name;

    lines.push('BEAT ' + (i + 1));

    lines.push('  Type     : ' + b.type.toUpperCase());

    lines.push('  Sender   : ' + roleName);

    lines.push('  Content  : ' + b.text);

    lines.push('  Shot Note: ' + (b.shotNotes || '—'));

    lines.push('  Flags    : ' + ((b.flags || []).join(', ') || 'none'));

    lines.push('');

  });



  lines.push('PRODUCTION NOTES');

  lines.push('• Maintain consistent UI bar / notch / carrier / battery across all shots.');

  lines.push('• Preserve bubble colors per role. Use neutral gray for status beats.');

  lines.push('• Keep text scale, padding, and corner radius uniform within the chat app skin.');

  lines.push('• For image beats, supply final asset or on-set placeholder matching described framing.');

  return lines.join('\n');

}



function openBrief() {

  refs.briefOutput.textContent = generateBrief();

