  refs.projectTime.addEventListener('input', updateProject);

  refs.projectCarrier.addEventListener('input', updateProject);



  document.querySelectorAll('.add-beat-bar button').forEach(function (btn) {

    btn.addEventListener('click', function () { addBeat(btn.getAttribute('data-beat-type')); });

  });

}



/* ===================== UTILS ===================== */

function toast(msg) {

  refs.toast.textContent = msg;

  refs.toast.classList.add('show');

  setTimeout(function () { refs.toast.classList.remove('show'); }, 2200);

}



init();

